if(path==='/api/product-connections/verify'){
 if(!(context.legacyOwner&&context.actorId)&&!verifiedFleetIt)fail16('An active COS Owner or verified IT account is required.',403);
 if(method!=='POST'||new URL(request.url).search)fail16('Use an explicit POST for verification.',405);
 try{
  if(body===null)body=await requestBody(request);
  const read=async(signal)=>{
   const bounded=CosProductTcpDisabledStage.cancellableIo(Date.now()+24000,Date.now,signal);
   const [full,checks]=await bounded.request(s=>Promise.all([
    CosProductTcpDisabledStage.createProtectedSourceReader(cosProductSourceContext(context))(s),
    legacyAll('camera_health_current?select=camera_device_id,port_status&order=camera_device_id.asc',context.headers,s)
   ]),24000);
   const source=await CosProductTcpDisabledStage.productResourceMembership(full);
   const byId=new Map(checks.map(r=>[String(r.camera_device_id),r]));
   if(byId.size!==checks.length)throw Error('Saved checks have conflicting identities.');
   const devices=full.identitySources.devices;
   return {census:source.census,tracker:full.tracker,devices,endpoints:devices.map(d=>({deviceId:d.id,publicIp:d.public_ip,expectedPorts:d.expected_ports,connectionRevision:d.connection_revision,monitoringEnabled:d.monitoring_enabled,activationState:d.activation_state,portStatus:byId.get(String(d.id))?.port_status||null}))};
  };
  return json(await verifyProductsNow(body,{
   read,signal:request.signal,
   classify:s=>CosProductTcpDisabledStage.buildTrackerIpReachability(s.census,s.tracker,s.endpoints),
   check:(d,signal)=>CosInlineCameraDiagnostics.checkSavedCamera({id:String(d.id),body:{unitKey:d.unit_key,publicIp:d.public_ip,ports:d.expected_ports,mode:'ports'},headers:context.headers,fetcher:requestFetch,signal})
  }));
 }catch(error){return json({error:'Verification could not be confirmed. Refresh saved results before retrying; check the current tracker IP and enabled ports.'},503);}
}
